<?php
 namespace Pterodactyl\Http\ViewComposers; use Illuminate\View\View; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Services\Dezerx\Billing\Billing; use Pterodactyl\Services\Dezerx\Ai\Ai; use Pterodactyl\Services\Dezerx\Demo; use Pterodactyl\Services\Dezerx\ServerCreate\ServerCreate; use Pterodactyl\Services\Dezerx\Subdomains\Subdomains; use Pterodactyl\Services\Dezerx\Theme; use Pterodactyl\Services\Dezerx\Staff\Staff; use Pterodactyl\Services\Dezerx\Appearance; use Pterodactyl\Services\Helpers\AssetHashService; class AssetComposer { public function __construct(private AssetHashService $assetHashService) { } public function compose(View $view): void { $view->with('asset', $this->assetHashService); $view->with('siteConfiguration', [ 'name' => config('app.name') ?? 'Pterodactyl', 'locale' => config('app.locale') ?? 'en', 'recaptcha' => [ 'enabled' => config('recaptcha.enabled', false), 'provider' => config('recaptcha.provider') === 'turnstile' ? 'turnstile' : 'recaptcha', 'siteKey' => (config('recaptcha.provider') === 'turnstile' ? config('recaptcha.turnstile_website_key') : config('recaptcha.website_key')) ?? '', ], 'dezerx' => [ 'theme' => Theme::payload(), 'appearance' => Appearance::payload(), 'addons' => Addons::payload(), 'billing' => Billing::payload(), 'subdomains' => Subdomains::payload(), 'serverCreate' => ServerCreate::payload(), 'ai' => Ai::payload(request()->user()), 'staff' => Staff::payload(request()->user()), 'demo' => Demo::payload(), ], ]); } } 